This is a **breaking API change** from the previous signature. The old `updateMany` accepted `(object, data, filters)` and returned a `Promise<number>`, while the new signature accepts `(object, records, options)` and returns a `Promise<BatchUpdateResponse>`.

Users upgrading will need to change:
- OLD: `updateMany('todo', { status: 'done' }, { priority: 1 })`
- NEW: `updateMany('todo', [{ id: '1', data: { status: 'done' } }], options)`

Consider:
1. Adding a migration guide to the README or CHANGELOG
2. Providing a deprecation path if backward compatibility is needed
3. Documenting this as a breaking change in release notes
```suggestion
      object: string,
      dataOrRecords: Partial<T> | Array<{ id: string; data: Partial<T> }>,
      filtersOrOptions?: Record<string, any> | BatchOptions
    ): Promise<BatchUpdateResponse | number> => {
        const route = this.getRoute('data');

        // New API shape: records array + BatchOptions → BatchUpdateResponse
        if (Array.isArray(dataOrRecords)) {
          const request: UpdateManyRequest = {
            records: dataOrRecords,
            options: filtersOrOptions as BatchOptions | undefined
          };
          const res = await this.fetch(`${this.baseUrl}${route}/${object}/updateMany`, {
            method: 'POST',
            body: JSON.stringify(request)
          });
          return res.json();
        }

        // Legacy API shape: data + filters → number
        const legacyRequest = {
          data: dataOrRecords,
          filters: filtersOrOptions
        };
        const res = await this.fetch(`${this.baseUrl}${route}/${object}/updateMany`, {
          method: 'POST',
          body: JSON.stringify(legacyRequest)
        });
        const result = await res.json();

        // Prefer a plain number if returned; otherwise, try to derive a count
        if (typeof result === 'number') {
          return result;
        }

        if (result && typeof result === 'object') {
          if (typeof result.updated === 'number') {
            return result.updated;
          }
          if (typeof result.count === 'number') {
            return result.count;
          }
        }

        // Fallback: if no clear number can be derived, return 0 for legacy callers
        return 0;
